<style scoped>
/* ===================== SCAR BACKGROUND RIG ===================== */
.scar-bg {
  --ink: #7a0e12;
  --ink-dim: #3c0507;
  --ink-bright: #d5262c;
  --bg: #0b0505;

  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  /* Lock to the small viewport height so the omnibar appearing/disappearing
     on mobile never resizes (and re-centers) the background. `vh` is the
     fallback for browsers without `svh` support. */
  height: 100vh;
  height: 100svh;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
  background: var(--bg);
}

.scar-bg svg {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(78vw, 44.6vh);
  height: min(122vw, 66vh);
  /* Repeat with `svh` so the size is also stable when the mobile omnibar
     moves; `svh` overrides the `vh` fallback where supported. */
  width: min(78vw, 44.6svh);
  height: min(122vw, 66svh);
  transform: translate(-50%, -50%);
  overflow: visible;
}

.scar-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 42%, rgba(213, 38, 44, 0.16), transparent 58%);
}

/* base silhouette: solid ink fill, no stroke noise */
.glyph-fill .rune-primary {
  fill: var(--ink);
  stroke: none;
}

.glyph-fill .rune-secondary {
  fill: var(--ink-dim);
  stroke: none;
}

/* glowing energy tracing along the same exact paths, via <use> so geometry can never drift */
.trace-line use {
  fill: none;
  stroke: var(--ink-bright);
  stroke-width: 1.1;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

/* ===================== ANIMATION (opt-in only) ===================== */
@media (prefers-reduced-motion: no-preference) {

  .ritual-scar {
    transform-origin: 540px 841.5px;
    animation: scar-breathe 15s ease-in-out infinite;
    will-change: transform;
  }

  @keyframes scar-breathe {
    0% {
      transform: rotate(0deg) scale(1);
    }

    25% {
      transform: rotate(0.35deg) scale(1.006);
    }

    50% {
      transform: rotate(-0.2deg) scale(0.998);
    }

    75% {
      transform: rotate(0.4deg) scale(1.004);
    }

    100% {
      transform: rotate(0deg) scale(1);
    }
  }

  /* the base silhouette glows brighter in step with its own line being "written" */
  @keyframes ember-pulse {
    0% {
      opacity: 0.35;
      filter: drop-shadow(0 0 2px var(--ink-bright)) drop-shadow(0 0 4px var(--ink-dim));
    }

    40% {
      opacity: 0.95;
      filter: drop-shadow(0 0 10px var(--ink-bright)) drop-shadow(0 0 22px var(--ink-bright));
    }

    60% {
      opacity: 1;
      filter: drop-shadow(0 0 14px var(--ink-bright)) drop-shadow(0 0 30px var(--ink-bright));
    }

    100% {
      opacity: 0.35;
      filter: drop-shadow(0 0 2px var(--ink-bright)) drop-shadow(0 0 4px var(--ink-dim));
    }
  }

  .rune-primary {
    animation: ember-pulse 12s ease-in-out infinite;
  }

  .rune-secondary {
    animation: ember-pulse 14s ease-in-out infinite -4s;
  }

  /* written, then erased, then written again — a single continuous breath */
  @keyframes trace-breathe {
    0% {
      stroke-dashoffset: 1;
      opacity: 0;
    }

    12% {
      opacity: 0.9;
    }

    45% {
      stroke-dashoffset: 0;
      opacity: 1;
    }

    60% {
      stroke-dashoffset: 0;
      opacity: 1;
    }

    88% {
      opacity: 0.9;
    }

    100% {
      stroke-dashoffset: -1;
      opacity: 0;
    }
  }

  .trace-line use {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    animation-name: trace-breathe;
    animation-timing-function: cubic-bezier(.45, 0, .4, 1);
    animation-iteration-count: infinite;
    will-change: stroke-dashoffset, opacity;
  }

  .trace-primary {
    animation-duration: 12s;
    animation-delay: 0s;
  }

  .trace-secondary {
    animation-duration: 14s;
    animation-delay: -4s;
  }
}

